from medicaments import q,line,segment
from format_lecon import paras

def tobramycine(l):
 t=paras('Tobrex pommade ophtalmique, tobramycine à 3 mg/g, autorisation suisse n°45508. La notice commune couvre aussi le collyre n°44538. Réserver cet exemple à une blépharite bactérienne à germe sensible après évaluation ; il ne traite pas à lui seul une dysfonction meibomienne ou une infestation par Demodex.')
 t+=q('44538',segment('44538','\nPommade ophtalmique\nEn cas','Posologie chez les patients âgés'))
 t+=q('44538',segment('44538','Posologie chez les enfants et les adolescents','Remarque\n'))
 t+=q('44538',segment('44538','\nUtilisation chez les enfants et les adolescents\n','Remarque pour les porteurs'))
 t+=paras('La mention générale dès deux mois ne peut pas être appliquée au collyre sans ses précautions propres. Le collyre contient du bore : la notice interdit son utilisation avant deux ans et, pour les infections graves, avant douze ans. La pommade est une formulation distincte ; son emploi avant deux mois n’est pas recommandé.', 'Le protocole HUG propose dix jours de pommade pour la blépharite antérieure. Cette durée n’est pas fixée dans la rubrique posologique AIPS lue : elle relève de la prescription clinique, avec réévaluation. Ne pas transformer un schéma de blépharite en traitement suffisant d’un ulcère cornéen.')
 t+=q('44538',segment('44538','\nContre-indications\n','Mises en garde et précautions'))
 t+=q('44538',segment('44538','\nGrossesse, allaitement\n','Effet sur l’aptitude'))
 t+=paras('Arrêter et consulter devant une hypersensibilité. Éviter l’usage prolongé qui sélectionne des germes résistants ou des champignons ; en cas d’échec, revoir le diagnostic. Les allergies croisées aux aminoglycosides sont possibles.', 'Prudence en cas de maladie neuromusculaire, notamment myasthénie ou maladie de Parkinson. Une association à un aminoglycoside systémique demande une surveillance adaptée, dont la concentration sérique ; la notice ne fournit pas de correction rénale chiffrée pour cet exemple local.', 'Ne pas porter de lentilles pendant le traitement. Ne pas toucher l’œil avec l’embout ; espacer les préparations ophtalmiques de cinq à dix minutes conformément à la notice. La pommade peut brouiller la vision : attendre le retour à une vision normale avant de conduire.', 'Grossesse : usage seulement exceptionnel et indication impérative selon le texte cité. Allaitement : la décision entre arrêt de l’allaitement et arrêt du médicament dépend de la situation clinique, sans déclaration de sécurité automatique.')
 return l.subwindow('tobramycine','Tobramycine : pommade, indications et limites par âge',t,(1,18))

def ciprofloxacine(l):
 t=paras('Ciloxan collyre à 3 mg/ml, ciprofloxacine, autorisation suisse n°51898. L’exemple ci-dessous est le schéma AIPS de l’ulcère cornéen bactérien sensible, choisi et surveillé par l’ophtalmologue. Il n’est ni le schéma d’une conjonctivite ni un traitement des kératites fongiques, amibiennes ou herpétiques.')
 t+=q('51898',segment('51898','Collyre, solution\nAdultes et enfants dès 1 an:','Conjonctivite ou blépharite bactérienne'))
 t+=q('51898',segment('51898','Enfants et adolescents\n','Mises en garde et précautions'))
 t+=q('51898',line('51898',"Ne pas utiliser lors d'une infection"))
 t+=q('51898',segment('51898','\nGrossesse, allaitement\n','Effet sur l’aptitude'))
 t+=paras('La mention dès un an ne fournit pas de schéma validé pour un nourrisson plus jeune. La pommade n°55982 a sa propre posologie ; elle ne remplace pas goutte pour goutte le collyre. La fréquence très élevée, y compris nocturne, impose de vérifier que l’administration sera réellement possible.', 'Arrêter devant hypersensibilité ou signe de tendinite et consulter immédiatement. Un traitement prolongé peut sélectionner des bactéries ou champignons résistants ; l’échec impose une nouvelle évaluation et des prélèvements adaptés.', 'Le produit n’est pas indiqué pour une infection des structures oculaires profondes. Le conservateur peut irriter une cornée lésée ; l’ophtalmologue surveille tolérance et cicatrisation. Une infection grave peut nécessiter une autre stratégie locale ou systémique, choisie sur l’examen et la microbiologie.', 'Ne pas porter de lentilles. Ne pas contaminer l’embout ; attendre la disparition du flou avant de conduire. Les interactions spécifiques de la voie oculaire n’ont pas été étudiées ; ne pas déduire une absence totale de risque de la faible exposition générale.', 'Une grossesse impose de la prudence ; pendant l’allaitement l’indication est évaluée selon des critères stricts, conformément à la notice. Le traitement ne doit pas être modifié sans l’équipe qui surveille l’ulcère.')
 return l.subwindow('ciprofloxacine','Ciprofloxacine : schéma suisse de l’ulcère bactérien',t,(19,))

def dexamethasone(l):
 t=paras('Maxidex, suspension ophtalmique de dexaméthasone à 1 mg/ml, autorisation suisse n°30058. Son indication comprend les inflammations non infectieuses du segment antérieur répondant aux corticoïdes, dont iritis et uvéite. Cet exemple exige un examen spécialisé préalable ; il ne s’applique pas à une rougeur inexpliquée.')
 t+=q('30058',segment('30058','Adultes, adolescents et enfants à partir de 2 ans:','Contre-indications'))
 t+=q('30058',segment('30058','\nContre-indications\n','Mises en garde et précautions'))
 t+=q('30058',segment('30058','\nGrossesse, allaitement\n','Effet sur l’aptitude'))
 t+=paras('La dose est adaptée à la gravité et réduite progressivement selon l’examen. Ne pas arrêter brutalement un traitement intensif ou prolongé, notamment si une suppression surrénalienne est possible. Chez l’enfant de moins de deux ans, l’utilisation n’est pas recommandée.', 'La notice contre-indique notamment glaucome, lésions ou ulcères cornéens et les infections citées. Une uvéite associée à une hypertonie ou une infection nécessite donc une stratégie spécialisée différente de l’application automatique de cet exemple.', 'Surveiller pression intraoculaire, cornée, vision et signes infectieux. Une hypertonie peut apparaître plus rapidement chez l’enfant ; une utilisation prolongée expose aussi à cataracte et effets systémiques. Le corticoïde peut masquer une infection, retarder la cicatrisation et favoriser une perforation sur un tissu aminci.', 'Les mydriatiques associés peuvent augmenter le risque d’hypertonie. Les anti-inflammatoires non stéroïdiens locaux peuvent aggraver les problèmes de cicatrisation. Ritonavir, cobicistat et autres inhibiteurs du CYP3A4 augmentent le risque d’effets systémiques ; l’association nécessite une évaluation particulière.', 'Agiter le flacon avant emploi. L’occlusion nasolacrymale ou la fermeture douce des paupières diminue le passage général. Éviter les lentilles pendant l’inflammation ; ne pas conduire si la vision est floue. L’absence d’amélioration après sept à huit jours impose une autre évaluation selon la notice, sans attendre ce délai en cas d’aggravation.')
 return l.subwindow('dexamethasone','Dexaméthasone : uvéite non infectieuse et surveillance',t,(20,))

def atropine(l):
 t=paras('Atropine SDU Faure, collyre à 5 mg/ml, autorisation suisse n°46994. L’indication comprend prévention et rupture des synéchies postérieures de l’iritis et de l’iridocyclite.')
 t+=q('46994035',segment('46994035','\nPosologie/Mode d’emploi\n','Mises en garde et précautions'))
 t+=q('46994035',segment('46994035','\nGrossesse, allaitement\n','Effets indésirables'))
 t+=paras('L’atropine dilate la pupille et paralyse l’accommodation. Son emploi demande l’évaluation de l’angle et de la pression ; le glaucome et le glaucome à angle étroit sont contre-indiqués dans cette notice.', 'Prudence chez l’enfant, le sujet âgé et en cas d’hyperthyroïdie, d’hypertension ou de maladie cardiovasculaire. Des intoxications systémiques sont possibles même aux doses thérapeutiques chez de petits enfants. Informer les proches des signes anticholinergiques tels qu’agitation, sécheresse, fièvre et tachycardie ; garder les unidoses hors de portée.', 'Rechercher les médicaments qui renforcent l’effet anticholinergique, notamment certains antidépresseurs, antihistaminiques et antiparkinsoniens. L’allaitement doit être interrompu selon la notice citée. La conduite et les machines dangereuses sont interdites pendant le traitement et dans les quelques jours suivants.', 'Ne pas contaminer l’embout et jeter l’unidose entamée. Le délai avant reprise des lentilles n’est pas une autorisation de les porter sur un œil inflammatoire.')
 return l.subwindow('atropine','Atropine : synéchies, contre-indications et effets généraux',t,(22,))

def uveite(l):return paras(dexamethasone(l),atropine(l))

def acetazolamide(l):
 t=paras('Diamox, acétazolamide : comprimés à 250 mg n°21191 et préparation injectable à 500 mg n°22002. La notice suisse est commune aux deux formes. Cet exemple s’intègre à la prise en charge urgente spécialisée ; il ne remplace pas le traitement du mécanisme de fermeture.')
 t+=q('21191',segment('21191','Glaucome:\nAdultes:\n','Oedèmes :'))
 t+=q('21191',segment('21191','Emploi de la préparation injectable:\n','Utilisation des comprimés:'))
 t+=q('21191',segment('21191','Administration chez les enfants et les adolescents:\n','Mises en garde et précautions'))
 t+=q('21191',segment('21191','\nGrossesse, allaitement\n','Effet sur l’aptitude'))
 t+=paras('Le schéma européen peut différer de la posologie AIPS citée. Ne pas présenter une dose européenne comme si elle figurait dans la notice suisse. Le prescripteur choisit la dose et la voie en fonction du terrain, des vomissements et du protocole applicable.', 'La phrase AIPS sur l’adjonction d’un myotique ne constitue pas une consigne universelle. Un mécanisme cristallinien ou rétrocristallinien peut être aggravé par un myotique ; le choix dépend de l’examen spécialisé.', 'Avant administration, rechercher allergie aux sulfamides, hyponatrémie, hypokaliémie, acidose et atteinte rénale ou hépatique. Respecter l’ensemble des contre-indications citées, y compris l’insuffisance corticosurrénalienne. La pédiatrie n’a pas été étudiée dans cette information professionnelle.', 'Surveiller électrolytes, fonction rénale et état acido-basique selon la situation. Arrêter devant réaction cutanée sévère, hypersensibilité ou suspicion d’œdème pulmonaire non cardiogénique ; ne pas réadministrer après un tel œdème imputé à l’acétazolamide.', 'Un épanchement choroïdien peut provoquer une baisse visuelle ou une douleur après l’introduction du médicament. Cette situation impose un arrêt rapide et une réévaluation spécialisée, pas une augmentation réflexe de la dose.', 'Revoir notamment salicylés à forte dose, autres diurétiques, digoxine, anticoagulants, antiépileptiques, lithium, ciclosporine et méthotrexate. L’association à d’autres inhibiteurs de l’anhydrase carbonique n’est pas recommandée par la notice ; toute association spécialisée doit être explicitement évaluée.', 'Le traitement de la crise reste surveillé. Une amélioration de la pression ne dispense pas de lever un bloc pupillaire et de protéger l’autre œil lorsque cela est indiqué.')
 return l.subwindow('acetazolamide','Acétazolamide : formes suisses, dose et exclusions',t,(21,26))
